/* 이미지가 없을 때 깨지지 않도록 대체 그래픽으로 전환 */
window.addEventListener('error', function(e){
  var t = e.target; if (!t || t.tagName !== 'IMG') return;
  var box = t.closest('[data-ph]'); if (box) box.classList.add('noimg');
  t.style.display = 'none';
}, true);
